type ListStorefrontProductsParams struct {
	CategorySlug pgtype.Text `json:"category_slug"`
	FeaturedOnly bool        `json:"featured_only"`
	SearchTerms  []string    `json:"search_terms"`
	PriceMin     int32       `json:"price_min"`
	PriceMax     int32       `json:"price_max"`
	OptionNames  []string    `json:"option_names"`
	OptionValues []string    `json:"option_values"`
	Sort         string      `json:"sort"`
	PageOffset   int32       `json:"page_offset"`
	PageLimit    int32       `json:"page_limit"`
}

// Storefront listings. The four queries below share one scope (an optional
// category with all its subcategories, featured_only and the search terms);
// count and list also share the price and option filters. Keep their WHERE
// clauses in sync. Search terms are lowercase letters and digits (listing.go).
// UNION (not UNION ALL) in the subtree CTE terminates even on a cycle.
func (q *Queries) ListStorefrontProducts(ctx context.Context, arg ListStorefrontProductsParams) ([]StorefrontProduct, error) {
	rows, err := q.db.Query(ctx, listStorefrontProducts,
		arg.CategorySlug,
		arg.FeaturedOnly,
		arg.SearchTerms,
		arg.PriceMin,
		arg.PriceMax,
		arg.OptionNames,
		arg.OptionValues,
		arg.Sort,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StorefrontProduct{}
	for rows.Next() {
		var i StorefrontProduct
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Slug,
			&i.CategoryID,
			&i.Description,
			&i.Features,
			&i.Images,
			&i.ImagePublicIds,
			&i.IsActive,
			&i.IsFeatured,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RatingCount,
			&i.RatingAvg,
			&i.VariantID,
			&i.SellingPrice,
			&i.OfferPrice,
			&i.Price,
			&i.InStock,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const productSlugExists = `-- name: ProductSlugExists :one
SELECT EXISTS (
  SELECT 1 FROM products WHERE slug = $1
) AS exists
`

func (q *Queries) ProductSlugExists(ctx context.Context, slug string) (bool, error) {
	row := q.db.QueryRow(ctx, productSlugExists, slug)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const updateProduct = `-- name: UpdateProduct :one
UPDATE products SET
    name = $2,
    slug = $3,
    description = $4,
    features = $5,
    images = $6,
    image_public_ids = $7,
    is_active = $8,
    is_featured = $9,
    category_id = $10
WHERE id = $1
RETURNING id, name, slug, category_id, description, features, images, image_public_ids, is_active, is_featured, created_at, updated_at, rating_count, rating_avg
`

type UpdateProductParams struct {
	ID             pgtype.UUID `json:"id"`
	Name           string      `json:"name"`
	Slug           string      `json:"slug"`
	Description    pgtype.Text `json:"description"`
	Features       []string    `json:"features"`
	Images         []string    `json:"images"`
	ImagePublicIds []string    `json:"image_public_ids"`
	IsActive       bool        `json:"is_active"`
	IsFeatured     bool        `json:"is_featured"`
	CategoryID     pgtype.UUID `json:"category_id"`
}

func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) (Product, error) {
	row := q.db.QueryRow(ctx, updateProduct,
		arg.ID,
		arg.Name,
		arg.Slug,
		arg.Description,
		arg.Features,
		arg.Images,
		arg.ImagePublicIds,
		arg.IsActive,
		arg.IsFeatured,
		arg.CategoryID,
	)
	var i Product
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.CategoryID,
		&i.Description,
		&i.Features,
		&i.Images,
		&i.ImagePublicIds,
		&i.IsActive,
		&i.IsFeatured,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RatingCount,
		&i.RatingAvg,
	)
	return i, err
}
